!function(r){function t(t){for(var e,n,m=t[0],o=t[1],c=t[2],s=0,g=[];s<m.length;s++)n=m[s],Object.prototype.hasOwnProperty.call(i,n)&&i[n]&&g.push(i[n][0]),i[n]=0;for(e in o)Object.prototype.hasOwnProperty.call(o,e)&&(r[e]=o[e]);for(u&&u(t);g.length;)g.shift()();return p.push.apply(p,c||[]),a()}function a(){for(var r,t=0;t<p.length;t++){for(var a,n=p[t],m=!0,o=1;o<n.length;o++)a=n[o],0!==i[a]&&(m=!1);m&&(p.splice(t--,1),r=e(e.s=n[0]))}return r}function e(t){if(n[t])return n[t].exports;var a=n[t]={i:t,l:!1,exports:{}};return r[t].call(a.exports,a,a.exports,e),a.l=!0,a.exports}var n={},i={3:0},p=[];e.m=r,e.c=n,e.d=function(r,t,a){e.o(r,t)||Object.defineProperty(r,t,{enumerable:!0,get:a})},e.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},e.t=function(r,t){if(1&t&&(r=e(r)),8&t)return r;if(4&t&&"object"==typeof r&&r&&r.__esModule)return r;var a=Object.create(null);if(e.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:r}),2&t&&"string"!=typeof r)for(var n in r)e.d(a,n,function(t){return r[t]}.bind(null,n));return a},e.n=function(r){var t=r&&r.__esModule?function(){return r.default}:function(){return r};return e.d(t,"a",t),t},e.o=function(r,t){return Object.prototype.hasOwnProperty.call(r,t)},e.p="";var m=window.webpackJsonp=window.webpackJsonp||[],o=m.push.bind(m);m.push=t,m=m.slice();for(var c=0;c<m.length;c++)t(m[c]);var u=o;p.push([25,0]),a()}({25:function(r,t,a){"use strict";a.r(t);var e=a(0);Object(e.a)("uk","army",a(26),a(1))},26:function(r){r.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"A15“十字军”巡航坦克","description":"<h6>综述：</h6><p>二战北非战事爆发后，英军急需一种新的坦克来替代战场上表现不佳的早期巡航坦克，于是在MK.Ⅴ (A13)“盟约者”MK.Ⅲ型巡航坦克基础上研制了MK.Ⅵ (A15)“十字军”巡航坦克，该坦克有Ⅰ型、Ⅱ型、Ⅲ型等多个型号，从1940年开始生产至1943年，一共生产了5300多辆，主要装备英军，也有一部分装备了加拿大军和澳大利亚军。“十字军”巡航坦克是非洲战场上英军装甲部队的主要装备，虽然其车速远超同期的德军坦克，但它因火力弱、装甲防护差和可靠性低等问题，与德军Ⅲ号和Ⅳ号坦克相比，仍难以在战场上占优。</p><p>“十字军”巡航坦克在退出前线后，很多被改装为指挥、工程、扫雷和防空等变形坦克用。</p><p>经过非洲沙漠的实战，发现了“盟约者”和“十字军”巡航坦克的许多不足之处，英国又在MK.Ⅲ巡航坦克的基础上新研发了一种叫“骑士”（MK.VII A24）的巡航坦克，但由于上马匆忙，该坦克性能仍末理想，因此“骑士”在作了小规模生产后就停产了，也未参加过实战，也难见其留存的身影。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}MK.Ⅵ (A15)“十字军”MK.Ⅰ型巡航坦克<br>隶属英军第22装甲旅的一辆MK.Ⅵ (A15)“十字军”MK.Ⅰ型巡航坦克，该坦克1941年11月在非洲战场被德军击毁。{{image}}imgs/uk/army/uk_army_tankcr_11.jpg{{text}}MK.Ⅵ (A15)“十字军”MK.Ⅱ型巡航坦克<br>1941年12月，北非利比亚战场，英军第22装甲旅的一辆MK.Ⅵ (A15)“十字军”MK.Ⅱ型巡航坦克。{{image}}imgs/uk/army/uk_army_tankcr_12.jpg{{text}}MK.Ⅵ (A15)“十字军”MK.Ⅱ型巡航坦克<br>1941年12月，北非利比亚战场，英军第1装甲师第9女王骑兵团一辆MK.Ⅵ (A15)“十字军”MK.Ⅱ型巡航坦克。{{image}}imgs/uk/army/uk_army_tankcr_13.jpg","description":"<h6>MK.Ⅵ (A15)“十字军”巡航坦克</h6><p> “十字军”巡航坦克保留了“盟约者”坦克的炮塔和发动机，但悬挂装置内每侧负重轮从4个变为5个，从而使坦克运行更平稳。</p><p>“十字军”MK.Ⅰ型和MK.Ⅱ型保留了2磅（40mm)火炮，Ⅰ型仍保留一个机枪炮塔，而Ⅱ型则取消了机枪炮塔，乘员也由5人减为4人，装甲比Ⅰ型加厚了6-10mm；“十字军”MK.Ⅲ型换上了6磅（57mm）火炮，乘员减为3人（取消了机枪手和装填手）。后来还有一种“十字军”ⅡCS“型，换装了76.2mm近距离支援榴弹炮。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂装置每侧有5个大直径负重轮。</li><li>车身较低矮，炮塔与“盟约者”坦克相似。</li><li>Ⅰ型车体前方有一个机枪炮塔，而Ⅱ型与Ⅲ型则取消了这个机枪炮塔。</li></ol></span>","caption":""},{"image":"{{text}}MK.Ⅵ (A15)“十字军”MK.Ⅲ型巡航坦克{{image}}imgs/uk/army/uk_army_tankcr_21.jpg{{text}}MK.Ⅵ (A15)“十字军”MK.Ⅲ型巡航坦克<br>1943年，北非突尼斯战场，英军第6装甲师的一辆MK.Ⅵ (A15)“十字军”MK.Ⅲ型巡航坦克。{{image}}imgs/uk/army/uk_army_tankcr_22.jpg{{text}}MK.Ⅵ (A15)“十字军”MK.ⅢA型巡航坦克<br>1944年7月，英军第1装甲师第10马步枪团一辆MK.Ⅵ (A15)“十字军”MK.ⅢA型巡航坦克。{{image}}imgs/uk/army/uk_army_tankcr_23.jpg","description":"<h6>“十字军”MK.Ⅲ型巡航坦克</h6><p>车长：6.0m，车宽：2.6m, 车高：2.2m，车重：约20.0t，乘员：3人；</p><p>最高车速：43km/h，最大行程：320km；</p><p>装甲厚度：7-49mm；</p><p>武器装备：</p><p>VII型：一门6磅（57mm）火炮和一挺机枪。</p>","caption":""}],"part2title":"战场上的“十字军”巡航坦克","part2description":"<p>1941年6月在非洲沙漠，英军第7装甲师所属第7 装甲旅刚装备的“十字军”巡航坦克在英军的“战斧行动”中第一次参加了实战，但在德军的Ⅲ号和Ⅳ号坦克的坦克炮和反坦克炮火攻击下，“十字军”坦克的薄弱装甲纷纷被击穿致坦克起火，战斗一开始就被击毁了17辆。紧接着200多辆“十字军”巡航坦克又参加了同年11月英军发起的“十字军”行动，但在德军的炮火下，其装甲的薄弱仍是致命的，特别是面对德军的88高炮的直射，更是根本无还手之力。非洲战事结束后，“十字军”巡航坦克大部分退出了前线改作了其它用途。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankcr_31.jpg","description":"一辆英军“十字军”Ⅰ型巡航坦克正在作越沟训练，“十字军”坦克速度高，机动性较好，也有较强的越野能力，但机械可靠性并不高，1941年刚进沙漠作战，就有不少在行进中抛锚。注意，这辆坦克车体前方有一个机枪炮塔，这在“十字军”巡航坦克中，唯有Ⅰ型坦克所具有。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_32.jpg","description":"正在向北非突尼斯战场进发的在一队英军“十字军”Ⅱ型和Ⅲ型巡航坦克，路边的指示牌上写有“哈迈”（突尼斯一地名）的大字标识。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_33.jpg","description":"一队行进在北非战场上的英军“十字军”Ⅲ型巡航坦克，由于“十字军”坦克装甲薄弱，坦克在德军反坦克炮火下生存率很低。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_34.jpg","description":"一队英军“十字军”Ⅱ型巡航坦克乘员正在休息，由于北非沙漠太阳猛烈，每辆坦克的乘员们都用坦克遮阳，睡在坦克的阴影下。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_35.jpg","description":"在北非沙漠战场上准备投入战斗的一辆英军“十字军”Ⅰ型坦克（右边）和一辆Ⅱ型坦克（左边），这二型坦克只装备了2磅火炮，火力弱，射程短，无法与德军的Ⅲ号与Ⅳ号坦克对抗。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_36.jpg","description":"北非沙漠战场，一辆“十字军”巡航坦克（可能是Ⅰ型）正驶过一辆被击毁的德军Ⅳ号坦克旁边，但击毁德军坦克应该不是这辆“十字军”巡航坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_37.jpg","description":"北非沙漠战场，一辆“十字军”巡航坦克乘员正在隐蔽地清洗炮管，坦克车体外用树枝作了伪装。这辆坦克应是Ⅲ型坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_38.jpg","description":"北非沙漠战场，“十字军”巡航坦克正在向德军阵地发动攻击。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_39.jpg","description":"北非沙漠战场，英军的“十字军”巡航坦克群正在冲击德军阵地。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_40.jpg","description":"1942年8月，北非沙漠战场，一辆隶属英军某装甲师编号为“T45128”的“十字军”Ⅱ型巡航坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankcr_41.jpg","description":"北非沙漠战场，一辆被德军缴获的“十字军”Ⅰ型巡航坦克，坦克车体上已挂上了德军的标识旗。战场上缴获的坦克，只要是设备完好，德军都会加以利用，变成自己的装备。","caption":""}]}')}});